package com.example.ragnarokdatabase.data.remote

import retrofit2.Retrofit
import retrofit2.converter.gson.GsonConverterFactory

/**
 * Object that exposes a single Retrofit instance configured to consume the Ragnarok API.
 * This way all collaborators (repositories, tests) reuse the same
 * base configuration without duplicating code.
 */
object NetworkModule {

    // For Android emulator: 10.0.2.2 points to the host's localhost (your PC)
    // For physical device: use your PC's IP on the network (e.g. 192.168.1.42)
    private const val BASE_URL = "http://64.176.16.51:8000/api/v1/"

    /**
     * Retrofit is created lazily to not initialize the network until it's actually
     * needed. GsonConverterFactory handles mapping JSON ↔ data class.
     */
    val api: RagnarokApiService by lazy {
        Retrofit.Builder()
            .baseUrl(BASE_URL)
            .addConverterFactory(GsonConverterFactory.create())
            .build()
            .create(RagnarokApiService::class.java)
    }
}

package com.example.ragnarokdatabase.data.remote

import retrofit2.Retrofit
import retrofit2.converter.gson.GsonConverterFactory

/**
 * Object that exposes a single Retrofit instance configured to consume the Ragnarok API.
 * This way all collaborators (repositories, tests) reuse the same
 * base configuration without duplicating code.
 */
object NetworkModule {

    // For Android emulator: 10.0.2.2 points to the host's localhost (your PC)
    // For physical device: use your PC's IP on the network (e.g. 192.168.1.42)
    private const val BASE_URL = "http://64.176.16.51:8000/api/v1/"

    /**
     * Returns the base URL for API endpoints (includes /api/v1/)
     */
    internal const val API_BASE_URL = BASE_URL

    /**
     * Returns the base URL for images (without /api/v1/)
     */
    internal const val IMAGE_BASE_URL = "http://64.176.16.51:8000/api/v1"

    /**
     * Retrofit is created lazily to not initialize the network until it's actually
     * needed. GsonConverterFactory handles mapping JSON ↔ data class.
     */
    val api: RagnarokApiService by lazy {
        Retrofit.Builder()
            .baseUrl(BASE_URL)
            .addConverterFactory(GsonConverterFactory.create())
            .build()
            .create(RagnarokApiService::class.java)
    }
}

package com.example.ragnarokdatabase.data.remote

import com.example.ragnarokdatabase.model.Item
import com.example.ragnarokdatabase.model.Monster
import com.example.ragnarokdatabase.model.PopularItemsResponse
import retrofit2.http.GET
import retrofit2.http.Path
import retrofit2.http.Query

/**
 * Declaration of the endpoints we use from the Ragnarok API.
 * Retrofit generates the concrete implementation based on this interface.
 */
interface RagnarokApiService {

    /**
     * Retrieves the details of an item by its ID.
     * The API accepts the numeric identifier in the endpoint.
     */
    @GET("items/{id}")
    suspend fun getItem(@Path("id") itemId: Int): Item

    /**
     * Retrieves the details of a monster by its ID.
     * The API accepts the numeric identifier in the endpoint.
     */
    @GET("monsters/{id}")
    suspend fun getMonster(@Path("id") monsterId: Int): Monster

    /**
     * Gets popular items according to the specified time period.
     * period can be: today, yesterday, last7days, last30days
     * limit controls how many items the response brings (default 10)
     */
    @GET("items/popular/{period}")
    suspend fun getPopularItems(
        @Path("period") period: String,
        @Query("limit") limit: Int = 10
    ): PopularItemsResponse

    /**
     * Universal search for items.
     * If query is a number → searches by ID
     * If query is text → partial search by name (case-insensitive)
     * limit controls how many items the response brings (default 50, max 500)
     */
    @GET("items/search")
    suspend fun searchItems(
        @Query("query") query: String,
        @Query("limit") limit: Int = 50
    ): List<Item>
}

package com.example.ragnarokdatabase.data.remote

import com.example.ragnarokdatabase.model.Item
import com.example.ragnarokdatabase.model.Monster
import com.example.ragnarokdatabase.model.PopularItemsResponse
import okhttp3.MultipartBody
import retrofit2.http.GET
import retrofit2.http.Multipart
import retrofit2.http.PUT
import retrofit2.http.Part
import retrofit2.http.Path
import retrofit2.http.Query

/**
 * Declaration of the endpoints we use from the Ragnarok API.
 * Retrofit generates the concrete implementation based on this interface.
 */
interface RagnarokApiService {

    /**
     * Retrieves the details of an item by its ID.
     * The API accepts the numeric identifier in the endpoint.
     */
    @GET("items/{id}")
    suspend fun getItem(@Path("id") itemId: Int): Item

    /**
     * Retrieves the details of a monster by its ID.
     * The API accepts the numeric identifier in the endpoint.
     */
    @GET("monsters/{id}")
    suspend fun getMonster(@Path("id") monsterId: Int): Monster

    /**
     * Gets popular items according to the specified time period.
     * period can be: today, yesterday, last7days, last30days
     * limit controls how many items the response brings (default 10)
     */
    @GET("items/popular/{period}")
    suspend fun getPopularItems(
        @Path("period") period: String,
        @Query("limit") limit: Int = 10
    ): PopularItemsResponse

    /**
     * Universal search for items.
     * If query is a number → searches by ID
     * If query is text → partial search by name (case-insensitive)
     * limit controls how many items the response brings (default 50, max 500)
     */
    @GET("items/search")
    suspend fun searchItems(
        @Query("query") query: String,
        @Query("limit") limit: Int = 50
    ): List<Item>

    /**
     * Upload collection image for an item.
     * Only accepts PNG files.
     */
    @Multipart
    @PUT("items/{item_id}/images/collection")
    suspend fun uploadCollectionImage(
        @Path("item_id") itemId: Int,
        @Part file: MultipartBody.Part
    ): Item
}

package com.example.ragnarokdatabase.data.repository

import com.example.ragnarokdatabase.data.remote.NetworkModule
import com.example.ragnarokdatabase.data.remote.RagnarokApiService
import com.example.ragnarokdatabase.model.Item
import com.example.ragnarokdatabase.model.PopularItem

/**
 * Encapsulates network access so that the rest of the layers don't know
 * whether the data comes from the web, cache, or a local database.
 * This is where we could combine multiple sources without changing the UI.
 */
class ItemRepository(
    private val api: RagnarokApiService = NetworkModule.api
) {
    /**
     * Queries the details of an item by its ID.
     */
    suspend fun getItem(itemId: Int): Item {
        return api.getItem(itemId)
    }

    /**
     * Gets popular items according to the time period.
     * period can be: today, yesterday, last7days, last30days
     */
    suspend fun getPopularItems(period: String, limit: Int = 10): List<PopularItem> {
        return api.getPopularItems(period, limit).items
    }

    /**
     * Searches for items by query (ID or name).
     * If query is a number, searches by ID.
     * If query is text, performs partial search by name.
     */
    suspend fun searchItems(query: String, limit: Int = 50): List<Item> {
        return api.searchItems(query, limit)
    }
}

package com.example.ragnarokdatabase.data.repository

import com.example.ragnarokdatabase.data.remote.NetworkModule
import com.example.ragnarokdatabase.data.remote.RagnarokApiService
import com.example.ragnarokdatabase.model.Item
import com.example.ragnarokdatabase.model.PopularItem
import okhttp3.MediaType.Companion.toMediaTypeOrNull
import okhttp3.MultipartBody
import okhttp3.RequestBody.Companion.asRequestBody
import java.io.File

/**
 * Encapsulates network access so that the rest of the layers don't know
 * whether the data comes from the web, cache, or a local database.
 * This is where we could combine multiple sources without changing the UI.
 */
class ItemRepository(
    private val api: RagnarokApiService = NetworkModule.api
) {
    /**
     * Queries the details of an item by its ID.
     */
    suspend fun getItem(itemId: Int): Item {
        return api.getItem(itemId)
    }

    /**
     * Gets popular items according to the time period.
     * period can be: today, yesterday, last7days, last30days
     */
    suspend fun getPopularItems(period: String, limit: Int = 10): List<PopularItem> {
        return api.getPopularItems(period, limit).items
    }

    /**
     * Searches for items by query (ID or name).
     * If query is a number, searches by ID.
     * If query is text, performs partial search by name.
     */
    suspend fun searchItems(query: String, limit: Int = 50): List<Item> {
        return api.searchItems(query, limit)
    }

    /**
     * Uploads a collection image for an item.
     * @param itemId The ID of the item
     * @param imageFile The PNG file to upload
     * @return Updated Item with new image
     */
    suspend fun uploadCollectionImage(itemId: Int, imageFile: File): Item {
        val requestBody = imageFile.asRequestBody("image/png".toMediaTypeOrNull())
        val multipartBody = MultipartBody.Part.createFormData(
            "file",
            imageFile.name,
            requestBody
        )
        return api.uploadCollectionImage(itemId, multipartBody)
    }
}

package com.example.ragnarokdatabase.model

import com.google.gson.annotations.SerializedName

/**
 * Base URL for image endpoints
 * Note: For Android emulator, 10.0.2.2 points to localhost on the host machine
 * Images are served under /api/v1
 */
private const val BASE_URL = "http://10.0.2.2:8000/api/v1"

data class Item(
    @SerializedName("id")
    val id: Int,

    @SerializedName("name")
    val name: String,

    @SerializedName("description")
    val description: String,

    @SerializedName("type")
    val type: String,

    @SerializedName("subtype")
    val subtype: String?,

    @SerializedName("buy_price")
    val buyPrice: Int,

    @SerializedName("sell_price")
    val sellPrice: Int,

    @SerializedName("stats")
    val stats: ItemStats,

    @SerializedName("required_level")
    val requiredLevel: Int,

    @SerializedName("required_job")
    val requiredJob: List<String>?,

    @SerializedName("gender")
    val gender: String?,

    @SerializedName("location")
    val location: String?,

    @SerializedName("sprite")
    val sprite: String,

    @SerializedName("script")
    val script: String?,

    @SerializedName("equip_script")
    val equipScript: String?,

    @SerializedName("unequip_script")
    val unequipScript: String?
) {
    fun getIconUrl(): String = "$BASE_URL/items/images/item/$id.png"
    fun getCollectionImageUrl(): String = "$BASE_URL/items/images/collection/$id.png"

    /**
     * Returns the required jobs as a comma-separated string, or null if no jobs required
     */
    fun getRequiredJobsText(): String? {
        return requiredJob?.joinToString(", ")
    }
}

data class ItemStats(
    @SerializedName("atk")
    val atk: Int?,

    @SerializedName("matk")
    val matk: Int?,

    @SerializedName("defense")
    val defense: Int?,

    @SerializedName("weight")
    val weight: Int,

    @SerializedName("slots")
    val slots: Int
)

data class PopularItem(
    @SerializedName("item_id")
    val id: Int,

    @SerializedName("name")
    val name: String,

    @SerializedName("type")
    val type: String,

    @SerializedName("view_count")
    val viewCount: Int,

    @SerializedName("sprite")
    val sprite: String? = null
) {
    fun getIconUrl(): String = "$BASE_URL/items/images/item/$id.png"
}

data class PopularItemsResponse(
    @SerializedName("period")
    val period: String,

    @SerializedName("items")
    val items: List<PopularItem>
)

package com.example.ragnarokdatabase.model

import com.example.ragnarokdatabase.data.remote.NetworkModule
import com.google.gson.annotations.SerializedName

data class Item(
    @SerializedName("id")
    val id: Int,

    @SerializedName("name")
    val name: String,

    @SerializedName("description")
    val description: String,

    @SerializedName("type")
    val type: String,

    @SerializedName("subtype")
    val subtype: String?,

    @SerializedName("buy_price")
    val buyPrice: Int,

    @SerializedName("sell_price")
    val sellPrice: Int,

    @SerializedName("stats")
    val stats: ItemStats,

    @SerializedName("required_level")
    val requiredLevel: Int,

    @SerializedName("required_job")
    val requiredJob: List<String>?,

    @SerializedName("gender")
    val gender: String?,

    @SerializedName("location")
    val location: String?,

    @SerializedName("sprite")
    val sprite: String,

    @SerializedName("script")
    val script: String?,

    @SerializedName("equip_script")
    val equipScript: String?,

    @SerializedName("unequip_script")
    val unequipScript: String?
) {
    fun getIconUrl(): String = "${NetworkModule.IMAGE_BASE_URL}/items/images/item/$id.png"

    /**
     * Returns the collection image URL with a timestamp to bypass cache
     * This ensures that when an image is updated, the new version is loaded
     */
    fun getCollectionImageUrl(): String {
        val timestamp = System.currentTimeMillis()
        return "${NetworkModule.IMAGE_BASE_URL}/items/images/collection/$id.png?t=$timestamp"
    }

    /**
     * Returns the required jobs as a comma-separated string, or null if no jobs required
     */
    fun getRequiredJobsText(): String? {
        return requiredJob?.joinToString(", ")
    }
}

data class ItemStats(
    @SerializedName("atk")
    val atk: Int?,

    @SerializedName("matk")
    val matk: Int?,

    @SerializedName("defense")
    val defense: Int?,

    @SerializedName("weight")
    val weight: Int,

    @SerializedName("slots")
    val slots: Int
)

data class PopularItem(
    @SerializedName("item_id")
    val id: Int,

    @SerializedName("name")
    val name: String,

    @SerializedName("type")
    val type: String,

    @SerializedName("view_count")
    val viewCount: Int,

    @SerializedName("sprite")
    val sprite: String? = null
) {
    fun getIconUrl(): String = "${NetworkModule.IMAGE_BASE_URL}/items/images/item/$id.png"
}

data class PopularItemsResponse(
    @SerializedName("period")
    val period: String,

    @SerializedName("items")
    val items: List<PopularItem>
)

package com.example.ragnarokdatabase.view

import androidx.compose.foundation.background
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.foundation.verticalScroll
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.automirrored.filled.ArrowBack
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.layout.ContentScale
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.style.TextAlign
import androidx.compose.ui.unit.dp
import androidx.lifecycle.viewmodel.compose.viewModel
import coil.compose.AsyncImage
import com.example.ragnarokdatabase.model.Item
import com.example.ragnarokdatabase.ui.theme.*
import com.example.ragnarokdatabase.viewmodel.ItemDetailUiState
import com.example.ragnarokdatabase.viewmodel.ItemDetailViewModel

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ItemDetailScreen(
    itemId: Int,
    onNavigateBack: () -> Unit,
    viewModel: ItemDetailViewModel = viewModel()
) {
    val uiState by viewModel.uiState.collectAsState()

    LaunchedEffect(itemId) {
        viewModel.loadItemDetail(itemId)
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(
                Brush.verticalGradient(
                    colors = listOf(
                        Slate900,
                        Slate950
                    )
                )
            )
    ) {
        when (val state = uiState) {
            is ItemDetailUiState.Loading -> {
                Box(
                    modifier = Modifier.fillMaxSize(),
                    contentAlignment = Alignment.Center
                ) {
                    CircularProgressIndicator(color = Amber400)
                }
            }
            is ItemDetailUiState.NotFound -> {
                NotFoundContent(onNavigateBack = onNavigateBack)
            }
            is ItemDetailUiState.Success -> {
                ItemDetailContent(
                    item = state.item,
                    onNavigateBack = onNavigateBack
                )
            }
            is ItemDetailUiState.Error -> {
                ErrorContent(
                    message = state.message,
                    onNavigateBack = onNavigateBack
                )
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ItemDetailContent(
    item: Item,
    onNavigateBack: () -> Unit
) {
    Column(
        modifier = Modifier
            .fillMaxSize()
            .verticalScroll(rememberScrollState())
    ) {
        // Top App Bar
        TopAppBar(
            title = { },
            navigationIcon = {
                IconButton(onClick = onNavigateBack) {
                    Icon(
                        imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                        contentDescription = "Back",
                        tint = Slate200
                    )
                }
            },
            colors = TopAppBarDefaults.topAppBarColors(
                containerColor = Slate900.copy(alpha = 0.95f)
            )
        )

        // Item Image
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(300.dp)
                .background(Slate800),
            contentAlignment = Alignment.Center
        ) {
            AsyncImage(
                model = item.getCollectionImageUrl(),
                contentDescription = item.name,
                modifier = Modifier
                    .size(200.dp)
                    .clip(RoundedCornerShape(16.dp)),
                contentScale = ContentScale.Fit
            )
        }

        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(24.dp)
        ) {
            // Item Name
            Text(
                text = item.name,
                style = MaterialTheme.typography.headlineLarge.copy(
                    fontFamily = LilitaOneFont
                ),
                color = Amber400,
                textAlign = TextAlign.Center,
                modifier = Modifier.fillMaxWidth()
            )

            Spacer(modifier = Modifier.height(8.dp))

            // Item Type
            Text(
                text = item.type + (item.subtype?.let { " - $it" } ?: ""),
                style = MaterialTheme.typography.titleMedium,
                color = Slate400,
                textAlign = TextAlign.Center,
                modifier = Modifier.fillMaxWidth()
            )

            Spacer(modifier = Modifier.height(32.dp))

            // Description
            Card(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(12.dp),
                colors = CardDefaults.cardColors(
                    containerColor = Slate800
                )
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(16.dp)
                ) {
                    Text(
                        text = "DESCRIPTION",
                        style = MaterialTheme.typography.titleSmall.copy(
                            fontFamily = LilitaOneFont
                        ),
                        color = Amber400
                    )
                    Spacer(modifier = Modifier.height(8.dp))
                    Text(
                        text = item.description,
                        style = MaterialTheme.typography.bodyMedium,
                        color = Slate200
                    )
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            // Price Info
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                PriceCard(
                    title = "BUY PRICE",
                    price = item.buyPrice,
                    modifier = Modifier.weight(1f)
                )
                PriceCard(
                    title = "SELL PRICE",
                    price = item.sellPrice,
                    modifier = Modifier.weight(1f)
                )
            }

            Spacer(modifier = Modifier.height(16.dp))

            // Stats Card
            Card(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(12.dp),
                colors = CardDefaults.cardColors(
                    containerColor = Slate800
                )
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(16.dp)
                ) {
                    Text(
                        text = "STATS",
                        style = MaterialTheme.typography.titleSmall.copy(
                            fontFamily = LilitaOneFont
                        ),
                        color = Amber400
                    )
                    Spacer(modifier = Modifier.height(12.dp))

                    item.stats.atk?.let {
                        StatRow(label = "Attack", value = it.toString())
                    }
                    item.stats.matk?.let {
                        StatRow(label = "Magic Attack", value = it.toString())
                    }
                    item.stats.defense?.let {
                        StatRow(label = "Defense", value = it.toString())
                    }
                    StatRow(label = "Weight", value = (item.stats.weight / 10).toString())
                    StatRow(label = "Slots", value = item.stats.slots.toString())
                }
            }

            // Requirements Card - Only show if there are meaningful requirements
            if (item.requiredLevel > 1 || item.requiredJob != null || item.gender != null || item.location != null) {
                Spacer(modifier = Modifier.height(16.dp))

                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp),
                    colors = CardDefaults.cardColors(
                        containerColor = Slate800
                    )
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(16.dp)
                    ) {
                        Text(
                            text = "REQUIREMENTS",
                            style = MaterialTheme.typography.titleSmall.copy(
                                fontFamily = LilitaOneFont
                            ),
                            color = Amber400
                        )
                        Spacer(modifier = Modifier.height(12.dp))

                        if (item.requiredLevel > 1) {
                            RequirementRow(label = "Level", value = item.requiredLevel.toString())
                        }
                        item.getRequiredJobsText()?.let {
                            RequirementRow(label = "Job", value = it)
                        }
                        item.gender?.let {
                            RequirementRow(label = "Gender", value = it)
                        }
                        item.location?.let {
                            RequirementRow(label = "Location", value = it)
                        }
                    }
                }
            }

            // Script Card - Show if any script exists
            if (item.script != null || item.equipScript != null || item.unequipScript != null) {
                Spacer(modifier = Modifier.height(16.dp))

                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp),
                    colors = CardDefaults.cardColors(
                        containerColor = Slate800
                    )
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(16.dp)
                    ) {
                        Text(
                            text = "SCRIPT",
                            style = MaterialTheme.typography.titleSmall.copy(
                                fontFamily = LilitaOneFont
                            ),
                            color = Amber400
                        )
                        Spacer(modifier = Modifier.height(12.dp))

                        item.script?.let { script ->
                            Text(
                                text = script,
                                style = MaterialTheme.typography.bodySmall.copy(
                                    fontFamily = androidx.compose.ui.text.font.FontFamily.Monospace
                                ),
                                color = Slate200
                            )
                        }

                        item.equipScript?.let { equipScript ->
                            Spacer(modifier = Modifier.height(12.dp))
                            Text(
                                text = "On Equip:",
                                style = MaterialTheme.typography.labelMedium,
                                color = Amber400
                            )
                            Spacer(modifier = Modifier.height(4.dp))
                            Text(
                                text = equipScript,
                                style = MaterialTheme.typography.bodySmall.copy(
                                    fontFamily = androidx.compose.ui.text.font.FontFamily.Monospace
                                ),
                                color = Slate200
                            )
                        }

                        item.unequipScript?.let { unequipScript ->
                            Spacer(modifier = Modifier.height(12.dp))
                            Text(
                                text = "On Unequip:",
                                style = MaterialTheme.typography.labelMedium,
                                color = Amber400
                            )
                            Spacer(modifier = Modifier.height(4.dp))
                            Text(
                                text = unequipScript,
                                style = MaterialTheme.typography.bodySmall.copy(
                                    fontFamily = androidx.compose.ui.text.font.FontFamily.Monospace
                                ),
                                color = Slate200
                            )
                        }
                    }
                }
            }

            Spacer(modifier = Modifier.height(40.dp))
        }
    }
}

@Composable
fun PriceCard(
    title: String,
    price: Int,
    modifier: Modifier = Modifier
) {
    Card(
        modifier = modifier,
        shape = RoundedCornerShape(12.dp),
        colors = CardDefaults.cardColors(
            containerColor = Slate800
        )
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(16.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Text(
                text = title,
                style = MaterialTheme.typography.labelSmall.copy(
                    fontFamily = LilitaOneFont
                ),
                color = Slate400
            )
            Spacer(modifier = Modifier.height(8.dp))
            Text(
                text = "${price}z",
                style = MaterialTheme.typography.titleLarge.copy(
                    fontWeight = FontWeight.Bold
                ),
                color = Amber400
            )
        }
    }
