@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ItemDetailScreen(
    itemId: Int,
    onNavigateBack: () -> Unit,
    viewModel: ItemDetailViewModel = viewModel()
) {
    val uiState by viewModel.uiState.collectAsState()

    LaunchedEffect(itemId) {
        viewModel.loadItemDetail(itemId)
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(
                Brush.verticalGradient(
                    colors = listOf(
                        Slate900,
                        Slate950
                    )
                )
            )
    ) {
        when (val state = uiState) {
            is ItemDetailUiState.Loading -> {
                Box(
                    modifier = Modifier.fillMaxSize(),
                    contentAlignment = Alignment.Center
                ) {
                    CircularProgressIndicator(color = Amber400)
                }
            }
            is ItemDetailUiState.NotFound -> {
                NotFoundContent(onNavigateBack = onNavigateBack)
            }
            is ItemDetailUiState.Success -> {
                ItemDetailContent(
                    item = state.item,
                    onNavigateBack = onNavigateBack,
                    viewModel = viewModel
                )
            }
            is ItemDetailUiState.Error -> {
                ErrorContent(
                    message = state.message,
                    onNavigateBack = onNavigateBack
                )
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ItemDetailContent(
    item: Item,
    onNavigateBack: () -> Unit,
    viewModel: ItemDetailViewModel
) {
    val context = LocalContext.current
    val uploadState by viewModel.uploadState.collectAsState()
    var showImageOptions by remember { mutableStateOf(false) }
    var tempPhotoUri by rememberSaveable { mutableStateOf<String?>(null) }

    // Permission launcher
    val permissionLauncher = rememberLauncherForActivityResult(
        ActivityResultContracts.RequestPermission()
    ) { isGranted ->
        if (isGranted) {
            showImageOptions = true
        }
    }

    // Camera launcher
    val cameraLauncher = rememberLauncherForActivityResult(
        ActivityResultContracts.TakePicture()
    ) { success ->
        if (success && tempPhotoUri != null) {
            try {
                val uri = Uri.parse(tempPhotoUri)
                val file = uriToFile(context, uri)
                if (file != null) {
                    viewModel.uploadCollectionImage(item.id, file)
                } else {
                    viewModel.resetUploadState()
                }
            } catch (e: Exception) {
                e.printStackTrace()
                viewModel.resetUploadState()
            }
        }
    }

    // Gallery launcher
    val galleryLauncher = rememberLauncherForActivityResult(
        ActivityResultContracts.GetContent()
    ) { uri ->
        uri?.let {
            val file = uriToFile(context, it)
            if (file != null) {
                viewModel.uploadCollectionImage(item.id, file)
            }
        }
    }

    // Show success/error snackbar
    LaunchedEffect(uploadState) {
        when (uploadState) {
            is ImageUploadState.Success -> {
                // Reset state after showing success
                kotlinx.coroutines.delay(2000)
                viewModel.resetUploadState()
            }
            else -> {}
        }
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .verticalScroll(rememberScrollState())
    ) {
        // Top App Bar
        TopAppBar(
            title = { },
            navigationIcon = {
                IconButton(onClick = onNavigateBack) {
                    Icon(
                        imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                        contentDescription = "Back",
                        tint = Slate200
                    )
                }
            },
            colors = TopAppBarDefaults.topAppBarColors(
                containerColor = Slate900.copy(alpha = 0.95f)
            )
        )

        // Item Image
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(300.dp)
                .background(Slate800),
            contentAlignment = Alignment.Center
        ) {
            AsyncImage(
                model = ImageRequest.Builder(context)
                    .data(item.getCollectionImageUrl())
                    .crossfade(true)
                    .build(),
                contentDescription = item.name,
                modifier = Modifier
                    .size(200.dp)
                    .clip(RoundedCornerShape(16.dp)),
                contentScale = ContentScale.Fit
            )

            // Upload image button
            FloatingActionButton(
                onClick = {
                    permissionLauncher.launch(android.Manifest.permission.CAMERA)
                },
                modifier = Modifier
                    .align(Alignment.BottomEnd)
                    .padding(16.dp),
                containerColor = Amber400
            ) {
                if (uploadState is ImageUploadState.Uploading) {
                    CircularProgressIndicator(
                        modifier = Modifier.size(24.dp),
                        color = Slate900
                    )
                } else {
                    Icon(
                        imageVector = Icons.Default.Add,
                        contentDescription = "Update Image",
                        tint = Slate900
                    )
                }
            }

            // Success indicator
            if (uploadState is ImageUploadState.Success) {
                Card(
                    modifier = Modifier
                        .align(Alignment.TopCenter)
                        .padding(16.dp),
                    colors = CardDefaults.cardColors(
                        containerColor = Amber400
                    )
                ) {
                    Text(
                        text = "Image updated successfully!",
                        modifier = Modifier.padding(horizontal = 16.dp, vertical = 8.dp),
                        color = Slate900,
                        style = MaterialTheme.typography.labelMedium
                    )
                }
            }

            // Error indicator
            if (uploadState is ImageUploadState.Error) {
                Card(
                    modifier = Modifier
                        .align(Alignment.TopCenter)
                        .padding(16.dp),
                    colors = CardDefaults.cardColors(
                        containerColor = Red400
                    )
                ) {
                    Text(
                        text = (uploadState as ImageUploadState.Error).message,
                        modifier = Modifier.padding(horizontal = 16.dp, vertical = 8.dp),
                        color = Slate100,
                        style = MaterialTheme.typography.labelMedium
                    )
                }
            }
        }

        // Image options dialog
        if (showImageOptions) {
            AlertDialog(
                onDismissRequest = { showImageOptions = false },
                title = {
                    Text(
                        text = "Update Image",
                        style = MaterialTheme.typography.titleLarge.copy(
                            fontFamily = LilitaOneFont
                        )
                    )
                },
                text = {
                    Text("Choose how to update the item image")
                },
                confirmButton = {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceEvenly
                    ) {
                        Button(
                            onClick = {
                                showImageOptions = false
                                try {
                                    val photoFile = createImageFile(context)
                                    val uri = FileProvider.getUriForFile(
                                        context,
                                        "${context.packageName}.fileprovider",
                                        photoFile
                                    )
                                    tempPhotoUri = uri.toString()
                                    cameraLauncher.launch(uri)
                                } catch (e: Exception) {
                                    e.printStackTrace()
                                }
                            },
                            colors = ButtonDefaults.buttonColors(
                                containerColor = Amber400
                            )
                        ) {
                            Icon(
                                imageVector = Icons.Default.Edit,
                                contentDescription = "Camera",
                                tint = Slate900
                            )
                            Spacer(modifier = Modifier.width(8.dp))
                            Text("Camera", color = Slate900)
                        }

                        Button(
                            onClick = {
                                showImageOptions = false
                                galleryLauncher.launch("image/*")
                            },
                            colors = ButtonDefaults.buttonColors(
                                containerColor = Slate700
                            )
                        ) {
                            Icon(
                                imageVector = Icons.Default.MoreVert,
                                contentDescription = "Gallery",
                                tint = Slate100
                            )
                            Spacer(modifier = Modifier.width(8.dp))
                            Text("Gallery", color = Slate100)
                        }
                    }
                },
                dismissButton = {
                    TextButton(onClick = { showImageOptions = false }) {
                        Text("Cancel")
                    }
                }
            )
        }

        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(24.dp)
        ) {
            // Item Name
            Text(
                text = item.name,
                style = MaterialTheme.typography.headlineLarge.copy(
                    fontFamily = LilitaOneFont
                ),
                color = Amber400,
                textAlign = TextAlign.Center,
                modifier = Modifier.fillMaxWidth()
            )

            Spacer(modifier = Modifier.height(8.dp))

            // Item Type
            Text(
                text = item.type + (item.subtype?.let { " - $it" } ?: ""),
                style = MaterialTheme.typography.titleMedium,
                color = Slate400,
                textAlign = TextAlign.Center,
                modifier = Modifier.fillMaxWidth()
            )

            Spacer(modifier = Modifier.height(32.dp))

            // Description
            Card(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(12.dp),
                colors = CardDefaults.cardColors(
                    containerColor = Slate800
                )
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(16.dp)
                ) {
                    Text(
                        text = "DESCRIPTION",
                        style = MaterialTheme.typography.titleSmall.copy(
                            fontFamily = LilitaOneFont
                        ),
                        color = Amber400
                    )
                    Spacer(modifier = Modifier.height(8.dp))
                    Text(
                        text = item.description,
                        style = MaterialTheme.typography.bodyMedium,
                        color = Slate200
                    )
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            // Price Info
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                PriceCard(
                    title = "BUY PRICE",
                    price = item.buyPrice,
                    modifier = Modifier.weight(1f)
                )
                PriceCard(
                    title = "SELL PRICE",
                    price = item.sellPrice,
                    modifier = Modifier.weight(1f)
                )
            }

            Spacer(modifier = Modifier.height(16.dp))

            // Stats Card
            Card(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(12.dp),
                colors = CardDefaults.cardColors(
                    containerColor = Slate800
                )
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(16.dp)
                ) {
                    Text(
                        text = "STATS",
                        style = MaterialTheme.typography.titleSmall.copy(
                            fontFamily = LilitaOneFont
                        ),
                        color = Amber400
                    )
                    Spacer(modifier = Modifier.height(12.dp))

                    item.stats.atk?.let {
                        StatRow(label = "Attack", value = it.toString())
                    }
                    item.stats.matk?.let {
                        StatRow(label = "Magic Attack", value = it.toString())
                    }
                    item.stats.defense?.let {
                        StatRow(label = "Defense", value = it.toString())
                    }
                    StatRow(label = "Weight", value = (item.stats.weight / 10).toString())
                    StatRow(label = "Slots", value = item.stats.slots.toString())
                }
            }

            // Requirements Card - Only show if there are meaningful requirements
            if (item.requiredLevel > 1 || item.requiredJob != null || item.gender != null || item.location != null) {
                Spacer(modifier = Modifier.height(16.dp))

                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp),
                    colors = CardDefaults.cardColors(
                        containerColor = Slate800
                    )
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(16.dp)
                    ) {
                        Text(
                            text = "REQUIREMENTS",
                            style = MaterialTheme.typography.titleSmall.copy(
                                fontFamily = LilitaOneFont
                            ),
                            color = Amber400
                        )
                        Spacer(modifier = Modifier.height(12.dp))

                        if (item.requiredLevel > 1) {
                            RequirementRow(label = "Level", value = item.requiredLevel.toString())
                        }
                        item.getRequiredJobsText()?.let {
                            RequirementRow(label = "Job", value = it)
                        }
                        item.gender?.let {
                            RequirementRow(label = "Gender", value = it)
                        }
                        item.location?.let {
                            RequirementRow(label = "Location", value = it)
                        }
                    }
                }
            }

            // Script Card - Show if any script exists
            if (item.script != null || item.equipScript != null || item.unequipScript != null) {
                Spacer(modifier = Modifier.height(16.dp))

                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp),
                    colors = CardDefaults.cardColors(
                        containerColor = Slate800
                    )
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(16.dp)
                    ) {
                        Text(
                            text = "SCRIPT",
                            style = MaterialTheme.typography.titleSmall.copy(
                                fontFamily = LilitaOneFont
                            ),
                            color = Amber400
                        )
                        Spacer(modifier = Modifier.height(12.dp))

                        item.script?.let { script ->
                            Text(
                                text = script,
                                style = MaterialTheme.typography.bodySmall.copy(
                                    fontFamily = androidx.compose.ui.text.font.FontFamily.Monospace
                                ),
                                color = Slate200
                            )
                        }

                        item.equipScript?.let { equipScript ->
                            Spacer(modifier = Modifier.height(12.dp))
                            Text(
                                text = "On Equip:",
                                style = MaterialTheme.typography.labelMedium,
                                color = Amber400
                            )
                            Spacer(modifier = Modifier.height(4.dp))
                            Text(
                                text = equipScript,
                                style = MaterialTheme.typography.bodySmall.copy(
                                    fontFamily = androidx.compose.ui.text.font.FontFamily.Monospace
                                ),
                                color = Slate200
                            )
                        }

                        item.unequipScript?.let { unequipScript ->
                            Spacer(modifier = Modifier.height(12.dp))
                            Text(
                                text = "On Unequip:",
                                style = MaterialTheme.typography.labelMedium,
                                color = Amber400
                            )
                            Spacer(modifier = Modifier.height(4.dp))
                            Text(
                                text = unequipScript,
                                style = MaterialTheme.typography.bodySmall.copy(
                                    fontFamily = androidx.compose.ui.text.font.FontFamily.Monospace
                                ),
                                color = Slate200
                            )
                        }
                    }
                }
            }

            Spacer(modifier = Modifier.height(40.dp))
        }
    }
}

